insert into games (id, data) values ('game-chrono-billiards', $j${"id":"game-chrono-billiards","title":"Chrono Billiards","slug":"chrono-billiards","kind":"embed","summary":"A 3D arcade pool game: read the angle and the speed right on the table, then sink the balls, K to 5th grade.","players":"1","minutes":5,"ageMin":5,"ageMax":11,"rules":["Pick your grade, from Kindergarten to 5th. Older grades get more balls and smaller pockets.","Pick Arcade to beat the clock, or Trick Shots to clear each table in a few shots.","Press anywhere on the table and pull back behind the white ball. The farther you pull, the faster it goes.","Read the table before you shoot: the angle of your aim, the speed from 1 to 10, where the white ball rolls and bounces, and the angle the ball you hit will take.","A ball bounces off a cushion at the same angle it came in. The table shows both angles.","In Kindergarten to 2nd grade, a pocket glows green and says In! when the ball you hit will drop in.","Let go to shoot. Bank the white ball off a cushion first for more points, and sink balls in a row for a combo.","If the white ball falls in, it goes back on its spot. On a keyboard, the arrow keys aim and set the speed, and Space shoots.","Sound is on: press the speaker button to turn it off."],"leadsTo":"act-marble-run","interactive":true,"path":"games/chrono-billiards.html","icon":"circle-dot","p1":"#BDEBE0","p2":"#7A1E4B","status":"published","featured":true,"createdAt":"2026-11-08T03:18:00.000Z","updatedAt":"2026-11-08T03:18:00.000Z","badge":"New","order":0,"cover":{"src":"assets/games/chrono-billiards.jpg","alt":"A 3D pool table with the aim drawn on the felt: 12 degrees from the white ball, a speed of 6 at 3.0 meters per second, the red ball's path at 24 degrees and a glowing pocket marked In!"},"vocabWord":"angle","vocabSay":"ANG-gul · noun","vocabMeaning":"How much two lines turn away from each other where they meet, measured in degrees.","vocabExample":"In Chrono Billiards, read the angle on the table before you shoot. A ball bounces off a cushion at the same angle it came in!"}$j$::jsonb)
